// Tests for WebPDecoderGpu (Images/WebP).
//
// Fixtures (TestData/WebP, generated by scripts/images/make_webp_fixtures.py with libwebp through Pillow) cover
// every libwebp effort method 0..6, palette bundling 1/2/4/8 pixels per word, all 14 predictor modes, the colour
// cache, meta prefix codes, 1x1 / 1xN / Nx1 / odd sizes, alpha with arbitrary RGB under alpha 0, ICC / EXIF / XMP
// carrying VP8X files and animations (hand-assembled ANMF with every blend / dispose combination, plus libwebp's own
// animation encoder). Lossy decoding is tested in CodecsTestBase.WebPLossyDecodeTests. The expected pixels (.rgba8.gz) are the SOURCE the
// lossless file was built from (the generator asserts libwebp decodes each file to exactly that); the expected
// animation canvases (.f<k>.rgba8.gz) are libwebp's WebPAnimDecoder output. Neither comes from this library.
//
// What can fail: the managed overload and the ArrayView1D overload (into a caller buffer pre-filled with 0xAB and
// longer than needed), the frame API, the prefix-code pool growth path (a decoder constructed with a tiny pool must
// grow it and still match), and the error paths, which must throw ImageDecodeException with the specific reason.

using System.IO.Compression;
using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.WebP;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string WebPFixturePrefix = "SpawnDev.Codecs.Demo.Shared.TestData.WebP.";

    private sealed record WebPFixtureRow(
        string Name, string Kind, int Width, int Height, bool HasAlpha, int Frames, int Orientation, string Truth);

    private static List<WebPFixtureRow> WebPManifest()
    {
        var text = System.Text.Encoding.UTF8.GetString(ReadEmbedded(WebPFixturePrefix + "manifest.tsv"));
        var rows = new List<WebPFixtureRow>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            if (line.Length == 0) continue;
            var c = line.Split('\t');
            rows.Add(new WebPFixtureRow(c[0], c[1], int.Parse(c[2]), int.Parse(c[3]), c[4] == "1", int.Parse(c[5]), int.Parse(c[6]), c[7]));
        }
        if (rows.Count == 0) throw new InvalidOperationException("The WebP manifest is empty.");
        return rows;
    }

    private static byte[] Gunzip(byte[] gz)
    {
        using var input = new MemoryStream(gz);
        using var gzs = new GZipStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream();
        gzs.CopyTo(output);
        return output.ToArray();
    }

    private static byte[] WebPFile(string name) => ReadEmbedded(WebPFixturePrefix + name + ".webp");

    private static byte[] WebPTruth(string name) => Gunzip(ReadEmbedded(WebPFixturePrefix + name + ".rgba8.gz"));

    private static byte[] WebPFrameTruth(string name, int k) => Gunzip(ReadEmbedded(WebPFixturePrefix + name + ".f" + k + ".rgba8.gz"));

    private static byte[] Poison(int length)
    {
        var fill = new byte[length];
        System.Array.Fill(fill, (byte)0xAB);
        return fill;
    }

    /// <summary>Decodes frame <paramref name="frame"/> (or the default image) into a poisoned, over-long caller buffer.</summary>
    private static async Task<(ImageInfo Info, byte[] Pixels)> WebPDecodeIntoViewAsync(
        Accelerator acc, WebPDecoderGpu dec, byte[] file, int expectedBytes, int? frame)
    {
        using var dFile = acc.Allocate1D<byte>(file.Length + 11);
        DeviceTransfer.Upload(dFile.View, file);
        using var dOut = acc.Allocate1D<byte>(expectedBytes + 7);
        DeviceTransfer.Upload(dOut.View, Poison((int)dOut.Length));
        var info = frame is null
            ? await dec.DecodeAsync(dFile.View, file.Length, dOut.View, PixelFormat.Rgba8)
            : await dec.DecodeFrameAsync(dFile.View, file.Length, frame.Value, dOut.View, PixelFormat.Rgba8);
        var pixels = await DeviceTransfer.DownloadAsync(dOut.View, expectedBytes);
        // The 7 bytes past the image must be untouched.
        var tail = await dOut.View.SubView(expectedBytes, 7).CopyToHostAsync();
        foreach (var b in tail)
            if (b != 0xAB) throw new Exception("decoder wrote past the end of the image");
        return (info, pixels);
    }

    private async Task CheckWebPStillFixturesAsync(int initialPoolInts, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc, initialPoolInts);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var row in WebPManifest().Where(r => r.Kind == "still"))
            {
                byte[] file = WebPFile(row.Name);
                byte[] expected = WebPTruth(row.Truth);
                try
                {
                    var managed = await dec.DecodeAsync(file);
                    var diff = ComparePixels(expected, managed.Pixels, 4, managed.Info.Width);
                    if (diff != null) failures.Add($"{row.Name} [managed]: {diff}");
                    if (managed.Info.Width != row.Width || managed.Info.Height != row.Height)
                        failures.Add($"{row.Name}: size {managed.Info.Width}x{managed.Info.Height}, expected {row.Width}x{row.Height}");

                    var (info, viewPixels) = await WebPDecodeIntoViewAsync(acc, dec, file, expected.Length, null);
                    diff = ComparePixels(expected, viewPixels, 4, info.Width);
                    if (diff != null) failures.Add($"{row.Name} [ArrayView1D]: {diff}");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{row.Name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(checkedCount > 30, $"only {checkedCount} fixtures were exercised");
            True(failures.Count == 0,
                $"{what}: {failures.Count} of {checkedCount + failures.Count} WebP fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_AllStillFixtures_MatchTruth_ManagedAndArrayView()
        => await CheckWebPStillFixturesAsync(1 << 18, "default pool");

    [TestMethod]
    public async Task WebPDecoderGpu_TinyPool_GrowsAndStillMatchesTruth()
        => await CheckWebPStillFixturesAsync(16, "pool starting at 16 ints");

    [TestMethod]
    public async Task WebPDecoderGpu_ReadInfo_ReportsFacts_ForEveryFixture()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var failures = new List<string>();
            foreach (var row in WebPManifest().Where(r => r.Kind != "source"))
            {
                try
                {
                    var info = await dec.ReadInfoAsync(WebPFile(row.Name));
                    if (info.Format != ImageFormat.WebP) failures.Add($"{row.Name}: format {info.Format}");
                    if (info.Width != row.Width || info.Height != row.Height)
                        failures.Add($"{row.Name}: size {info.Width}x{info.Height}, expected {row.Width}x{row.Height}");
                    if (info.HasAlpha != row.HasAlpha) failures.Add($"{row.Name}: HasAlpha {info.HasAlpha}, expected {row.HasAlpha}");
                    if (info.FrameCount != row.Frames) failures.Add($"{row.Name}: FrameCount {info.FrameCount}, expected {row.Frames}");
                    if (info.Orientation != row.Orientation) failures.Add($"{row.Name}: Orientation {info.Orientation}, expected {row.Orientation}");
                    if (info.BitDepth != 8) failures.Add($"{row.Name}: BitDepth {info.BitDepth}");
                }
                catch (Exception ex)
                {
                    failures.Add($"{row.Name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(failures.Count == 0, $"{failures.Count} ReadInfo mismatches:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task WebPDecoderGpu_FileInfoAndMetadata_MatchEmbeddedChunks()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var all = await dec.ReadMetadataAsync(WebPFile("meta_icc_exif_xmp_32x24"));
            NotNull(all.IccProfile, "ICC present");
            NotNull(all.Exif, "EXIF present");
            NotNull(all.Xmp, "XMP present");
            EqualBytes(ReadEmbedded(WebPFixturePrefix + "meta_icc_exif_xmp_32x24.icc"), all.IccProfile!, "ICC payload");
            EqualBytes(ReadEmbedded(WebPFixturePrefix + "meta_icc_exif_xmp_32x24.exif"), all.Exif!, "EXIF payload");
            EqualBytes(ReadEmbedded(WebPFixturePrefix + "meta_icc_exif_xmp_32x24.xmp"), all.Xmp!, "XMP payload");

            var fi = await dec.ReadFileInfoAsync(WebPFile("meta_icc_exif_xmp_32x24"));
            True(fi.IsExtended && fi.IsLossless && fi.HasIccProfile && fi.HasExif && fi.HasXmp, "VP8X facts");
            Equal(6, fi.Info.Orientation, "EXIF orientation 6");

            var onlyXmp = await dec.ReadMetadataAsync(WebPFile("meta_xmp_only_16x16"));
            True(onlyXmp.IccProfile is null && onlyXmp.Exif is null && onlyXmp.Xmp is not null, "only XMP");
            EqualBytes(ReadEmbedded(WebPFixturePrefix + "meta_xmp_only_16x16.xmp"), onlyXmp.Xmp!, "XMP payload");

            var simple = await dec.ReadFileInfoAsync(WebPFile("photo_80x60_m4"));
            True(!simple.IsExtended && simple.IsLossless && !simple.HasIccProfile && !simple.HasExif && !simple.HasXmp, "simple file facts");
            Equal(3, (await dec.ReadInfoAsync(WebPFile("meta_exif_alpha_40x30"))).Orientation, "EXIF orientation 3");

            var anim = await dec.ReadFileInfoAsync(WebPFile("anim_opaque_rects_bgcolor_64x48"));
            Equal(3, anim.LoopCount, "ANIM loop count");
            Equal(0xFF3366CCu, anim.BackgroundColor, "ANIM background colour");
            True(anim.IsLossless, "animation of VP8L frames");

            var lossy = await dec.ReadFileInfoAsync(WebPFile("lossy_32x32"));
            True(!lossy.IsLossless, "lossy file reports IsLossless = false");
            Equal(32, lossy.Info.Width, "lossy width");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private static List<ImageFrameInfo> WebPExpectedFrames(string name)
    {
        var text = System.Text.Encoding.UTF8.GetString(ReadEmbedded(WebPFixturePrefix + name + ".frames.tsv"));
        var frames = new List<ImageFrameInfo>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            if (line.Length == 0) continue;
            var c = line.Split('\t').Select(int.Parse).ToArray();
            frames.Add(new ImageFrameInfo(c[0], c[1], c[2], c[3], c[4], c[5],
                c[6] == 1 ? FrameDispose.Background : FrameDispose.None, c[7] == 1 ? FrameBlend.Over : FrameBlend.Source));
        }
        return frames;
    }

    [TestMethod]
    public async Task WebPDecoderGpu_ReadFrames_MatchesTheRiffChunks()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var failures = new List<string>();
            int count = 0;
            foreach (var row in WebPManifest().Where(r => r.Kind == "anim"))
            {
                var expected = WebPExpectedFrames(row.Name);
                var got = await dec.ReadFramesAsync(WebPFile(row.Name));
                count++;
                if (got.Length != expected.Count) { failures.Add($"{row.Name}: {got.Length} frames, expected {expected.Count}"); continue; }
                for (int i = 0; i < got.Length; i++)
                    if (got[i] != expected[i]) failures.Add($"{row.Name} frame {i}: {got[i]} != {expected[i]}");
            }
            // a still image is one frame covering the image
            var still = await dec.ReadFramesAsync(WebPFile("photo_80x60_m4"));
            Equal(1, still.Length, "still frame count");
            Equal(new ImageFrameInfo(0, 0, 0, 80, 60, 0, FrameDispose.None, FrameBlend.Source), still[0], "still frame");
            True(count >= 5, "animation fixtures were exercised");
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_Animations_EveryCanvasMatchesLibwebp_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var failures = new List<string>();
            int frameCount = 0;
            foreach (var row in WebPManifest().Where(r => r.Kind == "anim"))
            {
                byte[] file = WebPFile(row.Name);
                try
                {
                    // Default image of an animation = frame 0.
                    var first = await dec.DecodeAsync(file);
                    var d0 = ComparePixels(WebPFrameTruth(row.Name, 0), first.Pixels, 4, row.Width);
                    if (d0 != null) failures.Add($"{row.Name} DecodeAsync (default image): {d0}");

                    // Random access: last frame first, then ascending, then frame 0 again.
                    var order = new List<int> { row.Frames - 1 };
                    for (int k = 0; k < row.Frames; k++) order.Add(k);
                    order.Add(0);
                    foreach (int k in order)
                    {
                        byte[] expected = WebPFrameTruth(row.Name, k);
                        var managed = await dec.DecodeFrameAsync(file, k);
                        var diff = ComparePixels(expected, managed.Pixels, 4, row.Width);
                        if (diff != null) failures.Add($"{row.Name} frame {k} [managed]: {diff}");
                        var (info, px) = await WebPDecodeIntoViewAsync(acc, dec, file, expected.Length, k);
                        diff = ComparePixels(expected, px, 4, info.Width);
                        if (diff != null) failures.Add($"{row.Name} frame {k} [ArrayView1D]: {diff}");
                        frameCount++;
                    }
                }
                catch (Exception ex)
                {
                    failures.Add($"{row.Name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(frameCount > 20, $"only {frameCount} frames were exercised");
            True(failures.Count == 0, $"{failures.Count} animation mismatches:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task WebPDecoderGpu_FrameIndexOutOfRange_Throws()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            var anim = WebPFile("anim_thin_frames_7x9");
            bool threw = false;
            try { await dec.DecodeFrameAsync(anim, 4); }
            catch (ArgumentOutOfRangeException) { threw = true; }
            True(threw, "frame 4 of a 4-frame animation");
            threw = false;
            try { await dec.DecodeFrameAsync(WebPFile("photo_80x60_m4"), 1); }
            catch (ArgumentOutOfRangeException) { threw = true; }
            True(threw, "frame 1 of a still image");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private async Task AssertWebPRejectedAsync(byte[] file, string expectedMessagePart, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeAsync(file); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{what}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, what);
            Equal(ImageFormat.WebP, caught.Format, what + " format");
            // The decoder must still work afterwards.
            var ok = await dec.DecodeAsync(WebPFile("flat_32x24"));
            Equal(32, ok.Info.Width, what + ": decoder usable after the error");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_BadRiffSignature_IsRejected()
    {
        var file = WebPFile("photo_80x60_m4");
        file[1] = (byte)'X';
        await AssertWebPRejectedAsync(file, "not a WebP file", "bad RIFF signature");
        file = WebPFile("photo_80x60_m4");
        file[9] = (byte)'X';
        await AssertWebPRejectedAsync(file, "not a WebP file", "bad WEBP signature");
        await AssertWebPRejectedAsync(new byte[] { 1, 2, 3 }, "not a WebP file", "3 bytes");
    }

    [TestMethod(Timeout = 600000)]
    public async Task WebPDecoderGpu_TruncatedFile_IsRejected()
    {
        var file = WebPFile("photo_80x60_m4");
        await AssertWebPRejectedAsync(file.AsSpan(0, file.Length / 2).ToArray(), "truncated", "file cut in half");
        await AssertWebPRejectedAsync(file.AsSpan(0, 20).ToArray(), "truncated", "file cut after the first chunk header");
        var anim = WebPFile("anim_blend_dispose_64x48");
        await AssertWebPRejectedAsync(anim.AsSpan(0, anim.Length - 100).ToArray(), "truncated", "animation cut before the end");
    }

    /// <summary>Rewrites the RIFF + VP8L chunk sizes of a simple file so a cut in the bitstream is NOT caught by the container.</summary>
    private static byte[] CutVp8lStream(byte[] file, int keepPayload)
    {
        // simple file: "RIFF" size "WEBP" "VP8L" size payload...
        var cut = file.AsSpan(0, 20 + keepPayload).ToArray();
        BitConverter.GetBytes(cut.Length - 8).CopyTo(cut, 4);
        BitConverter.GetBytes(keepPayload).CopyTo(cut, 16);
        return cut;
    }

    [TestMethod]
    public async Task WebPDecoderGpu_BitstreamEndsEarly_IsRejected()
    {
        var file = WebPFile("mosaic_96x72");
        Equal((byte)'L', file[15], "fixture is a simple VP8L file");
        await AssertWebPRejectedAsync(CutVp8lStream(file, (file.Length - 20) / 2), "truncated", "VP8L stream cut in half inside valid RIFF framing");
        await AssertWebPRejectedAsync(CutVp8lStream(file, (file.Length - 20) - 3), "truncated", "VP8L stream missing its last bytes");
    }

    [TestMethod]
    public async Task WebPDecoderGpu_BadVp8lHeader_IsRejected()
    {
        var file = WebPFile("photo_80x60_m4");
        Equal((byte)0x2F, file[20], "VP8L signature byte");
        file[20] = 0x2E;
        await AssertWebPRejectedAsync(file, "invalid VP8L", "bad VP8L signature");
        file = WebPFile("photo_80x60_m4");
        file[24] |= 0xE0; // version bits 29..31 of the header word
        await AssertWebPRejectedAsync(file, "invalid VP8L", "VP8L version != 0");
    }

    [TestMethod]
    public async Task WebPDecoderGpu_Rgba16Request_IsRejected()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new WebPDecoderGpu(acc);
            bool threw = false;
            try { await dec.DecodeAsync(WebPFile("flat_32x24"), PixelFormat.Rgba16); }
            catch (ArgumentException) { threw = true; }
            True(threw, "WebP has no 16-bit output");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }
}
